do $release$
declare packet jsonb=$packet${"release":"20261023-est1-july2026-recalled","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","questions":[{"id":"f3454f11-6ff5-5df6-a27b-4a8cd2a3f3bd","track_id":"est","topic":"Ratios, percentages and unit conversion","difficulty":"medium","type":"mcq","stem":"The variable \\(m\\) varies jointly with \\(x^2\\) and \\(y\\). If \\(m=-1\\) when \\(x=3\\) and \\(y=5\\), what is the positive value of \\(x\\) when \\(y=8\\) and \\(m=-\\frac{1}{10}\\)?","choices":[{"key":"A","text":"\\(\\frac34\\)"},{"key":"B","text":"\\(\\frac32\\)"},{"key":"C","text":"\\(\\frac9{16}\\)"},{"key":"D","text":"2"},{"key":"E","text":"4"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-01","source_question_id":"EST1-JUL2026-RECALL-01","source_question_reference":"Recalled collection item 1; not an original exam number","source_pdf_page":1,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Ratios, percentages and unit conversion","lesson_subtopic":"Joint variation","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance."},"correct":"A","explanation":"Write m=kx^2y. Then -1=k(3^2)(5), so k=-1/45. Substituting the new values gives -1/10=(-1/45)x^2(8), hence x^2=9/16. The positive root is 3/4."},{"id":"e6101b30-588f-518a-b548-475121698bea","track_id":"est","topic":"Area and perimeter","difficulty":"medium","type":"mcq","stem":"The rectangle in the diagram has width \\(10-x\\) and height \\(7+x\\). The unshaded triangle has its base along the top edge and perpendicular height \\(x\\), where \\(0<x<10\\). Which expression gives the shaded area?","choices":[{"key":"A","text":"\\(70+2x-\\frac{x^2}{2}\\)"},{"key":"B","text":"\\(70-2x-\\frac{x^2}{2}\\)"},{"key":"C","text":"\\(70+3x-x^2\\)"},{"key":"D","text":"\\(70-7x-\\frac{x^2}{2}\\)"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-02","source_question_id":"EST1-JUL2026-RECALL-02","source_question_reference":"Recalled collection item 2; not an original exam number","source_pdf_page":2,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Area and perimeter","lesson_subtopic":"Composite shaded area","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance.","figure":"data:image/jpeg;base64,","figure_required":true,"content_edit_note":"Prompt clarified from the handwritten diagram; four instructor-written algebraic choices replace an unusable numeric response box. Original dimensions and shaded region preserved."},"correct":"B","explanation":"Subtract the unshaded triangle from the rectangle: (10-x)(7+x)-(1/2)(10-x)x=(10-x)(7+x/2)=70-2x-x^2/2. The source feedback of 12 is not an expression in x and is incorrect for this prompt."},{"id":"3b8234cd-fbd1-5cbe-a0cf-44cbaa608954","track_id":"est","topic":"Systems of equations","difficulty":"medium","type":"mcq","stem":"If \\(2a+x=8\\), \\(7x-y=-17\\), and \\(a+2y=11\\), what is the value of \\(a+x+y\\)?","choices":[{"key":"A","text":"4"},{"key":"B","text":"6"},{"key":"C","text":"8"},{"key":"D","text":"10"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-04","source_question_id":"EST1-JUL2026-RECALL-04","source_question_reference":"Recalled collection item 4; not an original exam number","source_pdf_page":3,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Systems of equations","lesson_subtopic":"Three-variable linear systems","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance."},"correct":"B","explanation":"From the first equation x=8-2a. The second gives y=7x+17=73-14a. Substitute into a+2y=11: -27a=-135, so a=5, x=-2 and y=3. Therefore a+x+y=6. Substitution satisfies all three equations."},{"id":"797e4220-c8de-5a40-a8e8-ddd9ddf20bd2","track_id":"est","topic":"Ratios, percentages and unit conversion","difficulty":"medium","type":"mcq","stem":"Suppose \\(m\\) varies jointly with \\(x^2\\) and \\(y\\). If \\(m=-1\\) when \\(x=3\\) and \\(y=5\\), find \\(m\\) when \\(x=6\\) and \\(y=10\\).","choices":[{"key":"A","text":"-2"},{"key":"B","text":"-4"},{"key":"C","text":"-8"},{"key":"D","text":"-12"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-05","source_question_id":"EST1-JUL2026-RECALL-05","source_question_reference":"Recalled collection item 5; not an original exam number","source_pdf_page":3,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Ratios, percentages and unit conversion","lesson_subtopic":"Joint variation","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance."},"correct":"C","explanation":"The constant is k=-1/(3^2*5)=-1/45. Thus m=(-1/45)*6^2*10=-8. Equivalently doubling x multiplies m by four, and doubling y multiplies it by two."},{"id":"8b2b384c-b101-542f-b5c4-9773e817b756","track_id":"est","topic":"Ratios, percentages and unit conversion","difficulty":"easy","type":"mcq","stem":"A car travels at a constant speed of 80 kilometers per hour. How many seconds does it take to travel 220 kilometers?","choices":[{"key":"A","text":"9900"},{"key":"B","text":"8800"},{"key":"C","text":"7700"},{"key":"D","text":"6600"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-06","source_question_id":"EST1-JUL2026-RECALL-06","source_question_reference":"Recalled collection item 6; not an original exam number","source_pdf_page":4,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Ratios, percentages and unit conversion","lesson_subtopic":"Distance, rate and time conversions","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance."},"correct":"A","explanation":"Time = distance/speed = 220/80 = 2.75 hours. Multiply by 3600 seconds per hour: 2.75*3600=9900 seconds."},{"id":"61a18238-a332-5336-9e26-a1fdd70d70b3","track_id":"est","topic":"Statistics and data analysis","difficulty":"medium","type":"mcq","stem":"The data set is \\(3,3,5,8,12,19,20,22,30,33,39,40,40,42\\). If \\(m\\) is the largest mode and \\(n\\) is the median, what is \\(nm\\)?","choices":[{"key":"A","text":"63"},{"key":"B","text":"420"},{"key":"C","text":"441"},{"key":"D","text":"840"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-07","source_question_id":"EST1-JUL2026-RECALL-07","source_question_reference":"Recalled collection item 7; not an original exam number","source_pdf_page":4,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Statistics and data analysis","lesson_subtopic":"Median and multimodal data","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance.","content_edit_note":"One answer choice corrected after independent verification; original wording and data preserved."},"correct":"D","explanation":"There are 14 ordered values, so the median is the mean of the 7th and 8th: (20+22)/2=21. Both 3 and 40 occur twice; the largest mode is 40. Therefore nm=21*40=840. The original four choices omitted 840 and the source feedback of 474 was incorrect."},{"id":"a3c98044-01bc-5a19-a01e-51a757823e0c","track_id":"est","topic":"Linear functions and slope","difficulty":"easy","type":"mcq","stem":"A customer buys a laptop using a 24-month installment plan. The total amount paid, \\(y\\) dollars, is modeled by \\(y=240+24x\\), where \\(x\\) is the monthly installment payment in dollars. What does 240 represent?","choices":[{"key":"A","text":"The number of months in the plan."},{"key":"B","text":"The total cost after all payments."},{"key":"C","text":"The initial down payment before monthly installments."},{"key":"D","text":"The amount of each monthly payment."}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-08","source_question_id":"EST1-JUL2026-RECALL-08","source_question_reference":"Recalled collection item 8; not an original exam number","source_pdf_page":5,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Linear functions and slope","lesson_subtopic":"Interpreting a linear-model intercept","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance."},"correct":"C","explanation":"The term 24x is the total of 24 monthly payments. The additional constant 240 is paid independently of those installments, so it is the initial down payment."},{"id":"96a0565b-8002-5ba0-9167-1e96bb4cd07f","track_id":"est","topic":"Linear functions and slope","difficulty":"easy","type":"mcq","stem":"Line \\(l\\) passes through \\((2,-3)\\) and \\((6,k)\\). If its slope is \\(\\frac52\\), what is \\(k\\)?","choices":[{"key":"A","text":"2"},{"key":"B","text":"5"},{"key":"C","text":"7"},{"key":"D","text":"10"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-09","source_question_id":"EST1-JUL2026-RECALL-09","source_question_reference":"Recalled collection item 9; not an original exam number","source_pdf_page":5,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Linear functions and slope","lesson_subtopic":"Slope from two points","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance."},"correct":"C","explanation":"The slope is (k-(-3))/(6-2)=(k+3)/4. Set this equal to 5/2: k+3=10, hence k=7."},{"id":"004faf2a-8526-5fe0-89c5-a535d9fa3ec2","track_id":"est","topic":"Triangles and similarity","difficulty":"medium","type":"mcq","stem":"Triangle \\(ABC\\) has vertex \\(A=(1,3)\\), and the midpoint of the opposite side \\(BC\\) is \\((1,-1)\\). What are the coordinates of the centroid?","choices":[{"key":"A","text":"\\((1,\\frac13)\\)"},{"key":"B","text":"\\((1,1)\\)"},{"key":"C","text":"\\((1,\\frac23)\\)"},{"key":"D","text":"\\((1,0)\\)"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-10","source_question_id":"EST1-JUL2026-RECALL-10","source_question_reference":"Recalled collection item 10; not an original exam number","source_pdf_page":6,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Triangles and similarity","lesson_subtopic":"Centroid divides a median in a 2:1 ratio","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance.","figure":"data:image/jpeg;base64,","figure_required":true},"correct":"A","explanation":"If M is the midpoint of BC, the centroid is G=(A+2M)/3. Thus G=((1+2*1)/3,(3+2*(-1))/3)=(1,1/3). This is two-thirds of the way from A to M."},{"id":"35d6badd-01c8-54dc-8a4a-426f8b7b2db7","track_id":"est","topic":"Triangles and similarity","difficulty":"easy","type":"mcq","stem":"A median of triangle \\(ABC\\) is drawn from \\(A=(1,3)\\) to the midpoint \\((1,-1)\\) of \\(BC\\). What is the equation of this median line?","choices":[{"key":"A","text":"\\(x=1\\)"},{"key":"B","text":"\\(x=5\\)"},{"key":"C","text":"\\(y=1\\)"},{"key":"D","text":"\\(y=x^2\\)"}],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_document":"EST I July 2026 - teacher-recalled collection","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_code":"EST1-JUL2026-RECALL-11","source_question_id":"EST1-JUL2026-RECALL-11","source_question_reference":"Recalled collection item 11; not an original exam number","source_pdf_page":7,"content_origin":"teacher_recalled_corrected","source_provenance_note":"Post-trial student recollection published by Mohamed Elminshawy; incomplete, not an authenticated official paper.","curriculum_lesson":"Triangles and similarity","lesson_subtopic":"Equation of a triangle median","lesson_taxonomy_version":"20260929","answer_review_status":"independently_solved","answer_review":"2026-10-23 independent exact arithmetic, algebra and original-page review","verified_release":"20261023-est1-july2026-recalled","practice_collection":"20261023-est1-july2026-recalled","difficulty_basis":"Instructor estimate; not calibrated from student performance.","figure":"data:image/jpeg;base64,","figure_required":true},"correct":"A","explanation":"Both endpoints of the median have x-coordinate 1. The line through them is vertical and has equation x=1."}],"held_questions":[{"id":"de71a180-b7e4-5aaa-8263-dd21d4b88811","track_id":"est","topic":"Area and perimeter","difficulty":"medium","type":"grid_in","stem":"July 2026 recalled collection item 3: Find the area in the graph shown. Source evidence only - the region and all necessary vertex coordinates are not specified.","choices":[],"assets":{"source":"EST I July 2026 - Minshawy teacher-recalled set (incomplete)","source_url":"https://minshawymath.com/wp-content/uploads/2026/07/2-2.pdf","source_article_url":"https://minshawymath.com/est-july-2026-collected-questions/","source_code":"EST1-JUL2026-RECALL-03","source_question_id":"EST1-JUL2026-RECALL-03","source_pdf_sha256":"b24ce3930562833e6f81edc483be164f18b006319f1b60adbf9b726006bee4d9","source_pdf_page":2,"content_origin":"teacher_recalled_source_hold","curriculum_lesson":"Area and perimeter","lesson_subtopic":"Area from a coordinate diagram","lesson_taxonomy_version":"20260929","figure":"data:image/jpeg;base64,","figure_required":true,"answer_review_status":"source_ambiguous","release_hold_reason":"The recalled graph lacks necessary vertex coordinates and a clearly defined region; the supplied numeric feedback cannot be independently justified. Preserve as evidence only.","practice_collection":"20261023-est1-july2026-recalled"},"correct":{"void":true},"explanation":"Held: do not grade. Missing vertex coordinates and ambiguous requested region prevent a unique verified area. No coordinates or replacement answer have been invented."}],"exam":{"id":"8f824625-f09c-5bbc-8a93-1f4c8ce8f669","track_id":"est","title":"EST I - July 2026 Recalled Questions - Verified Practice (10Q / 20 min)","assessment_type":"lesson_exam","duration_seconds":1200,"question_ids":["f3454f11-6ff5-5df6-a27b-4a8cd2a3f3bd","e6101b30-588f-518a-b548-475121698bea","3b8234cd-fbd1-5cbe-a0cf-44cbaa608954","797e4220-c8de-5a40-a8e8-ddd9ddf20bd2","8b2b384c-b101-542f-b5c4-9773e817b756","61a18238-a332-5336-9e26-a1fdd70d70b3","a3c98044-01bc-5a19-a01e-51a757823e0c","96a0565b-8002-5ba0-9167-1e96bb4cd07f","004faf2a-8526-5fe0-89c5-a535d9fa3ec2","35d6badd-01c8-54dc-8a4a-426f8b7b2db7"],"shuffle":false,"review_policy":"full_review","max_attempts":1,"is_published":true,"is_full_length":false,"scoring_map":null}}$packet$; p jsonb; ids uuid[]='{}'; all_ids uuid[]='{}'; ex uuid; group_row record; n integer; before_q bigint; before_k bigint; before_e bigint; before_a bigint; before_h text; after_h text; assignments_n integer:=0;
begin
 if exists(select 1 from public.audit_log where action='question.est1_july2026_recalled_20261023') then raise exception 'Release already applied'; end if;
 select count(*) into before_q from public.questions; select count(*) into before_k from public.question_keys; select count(*) into before_e from public.exams; select count(*) into before_a from public.assignments;
 select md5(string_agg(md5(jsonb_build_array(q.id,q.stem,q.choices,q.assets,k.correct,k.explanation)::text),'' order by q.id)) into before_h from public.questions q left join public.question_keys k on k.question_id=q.id;
 if not exists(select 1 from public.tracks where id='est' and is_active) then raise exception 'EST I track unavailable'; end if;
 for p in select value from jsonb_array_elements((packet->'questions')||(packet->'held_questions')) loop
  if p->>'track_id'<>'est' or exists(select 1 from public.questions where id=(p->>'id')::uuid or assets->>'source_code'=p->'assets'->>'source_code' or assets->>'source_question_id'=p->'assets'->>'source_question_id') then raise exception 'Conflicting question'; end if;
  if exists(select 1 from public.questions where track_id='est' and lower(regexp_replace(stem,'[^[:alnum:]]','','g'))=lower(regexp_replace(p->>'stem','[^[:alnum:]]','','g'))) then raise exception 'Duplicate stem'; end if;
  insert into public.questions(id,track_id,topic,difficulty,type,stem,choices,assets) values((p->>'id')::uuid,'est',p->>'topic',p->>'difficulty',p->>'type',p->>'stem',p->'choices',p->'assets');
  insert into public.question_keys(question_id,correct,explanation) values((p->>'id')::uuid,p->'correct',p->>'explanation');
  all_ids:=array_append(all_ids,(p->>'id')::uuid);
 end loop;
 select array_agg((q->>'id')::uuid order by ord) into ids from jsonb_array_elements(packet->'questions') with ordinality x(q,ord);
 if cardinality(ids)<>10 or cardinality(all_ids)<>11 or not portal_private.exam_content_ready(ids,'est') then raise exception 'Exam content not ready'; end if;
 if exists(select 1 from public.questions q join public.question_keys k on k.question_id=q.id where q.id=any(all_ids) and not(q.id=any(ids)) and portal_private.question_eligible(q,k,'est',false)) then raise exception 'Held item became eligible'; end if;
 if exists(select 1 from public.questions q join public.question_keys k on k.question_id=q.id where q.id=any(ids) and (jsonb_typeof(k.correct)<>'string' or not exists(select 1 from jsonb_array_elements(q.choices) c where c->>'key'=k.correct#>>'{}') or nullif(k.explanation,'') is null or q.assets ?| array['correct','answer','explanation'])) then raise exception 'Invalid answer isolation'; end if;
 ex:=(packet->'exam'->>'id')::uuid;
 insert into public.exams(id,track_id,title,duration_seconds,question_ids,shuffle,review_policy,max_attempts,is_published,is_full_length,assessment_type,scoring_map) values(ex,'est',packet->'exam'->>'title',1200,ids,false,'full_review',1,true,false,'lesson_exam',null);
 for group_row in select id from public.groups where track_id='est' loop
  insert into public.assignments(exam_id,group_id) values(ex,group_row.id); assignments_n:=assignments_n+1;
 end loop;
 insert into public.assignments(exam_id,user_id)
 select ex,e.user_id from public.enrollments e where e.track_id='est' and e.status='active' and not exists(select 1 from public.group_members gm join public.groups g on g.id=gm.group_id where gm.user_id=e.user_id and g.track_id='est');
 get diagnostics n=row_count; assignments_n:=assignments_n+n;
 if (select count(*) from public.questions)<>before_q+11 or (select count(*) from public.question_keys)<>before_k+11 or (select count(*) from public.exams)<>before_e+1 or (select count(*) from public.assignments)<>before_a+assignments_n then raise exception 'Unexpected row counts'; end if;
 select md5(string_agg(md5(jsonb_build_array(q.id,q.stem,q.choices,q.assets,k.correct,k.explanation)::text),'' order by q.id)) into after_h from public.questions q left join public.question_keys k on k.question_id=q.id where not(q.id=any(all_ids));
 if after_h is distinct from before_h then raise exception 'Existing questions changed'; end if;
 if exists(select 1 from jsonb_array_elements((packet->'questions')||(packet->'held_questions')) as candidate(item) join public.questions q on q.id=(candidate.item->>'id')::uuid join public.question_keys k on k.question_id=q.id where q.stem is distinct from candidate.item->>'stem' or q.assets is distinct from candidate.item->'assets' or q.choices is distinct from candidate.item->'choices' or k.correct is distinct from candidate.item->'correct' or k.explanation is distinct from candidate.item->>'explanation') then raise exception 'Readback mismatch'; end if;
 insert into public.audit_log(action,target_type,target_id,meta) values('question.est1_july2026_recalled_20261023','question_batch',packet->>'release',jsonb_build_object('verified_count',10,'held_count',1,'exam_id',ex,'question_ids',ids,'held_question_id',(packet->'held_questions'->0->>'id'),'assignment_count',assignments_n,'original_pdf_sha256',packet->>'source_pdf_sha256','existing_questions_preserved',true,'no_student_attempts_changed',true));
end $release$;
select id,title,cardinality(question_ids) as question_count,duration_seconds,is_published,portal_private.exam_content_ready(question_ids,track_id) as ready from public.exams where id='8f824625-f09c-5bbc-8a93-1f4c8ce8f669';
commit;
